"""Min-Max Stack with integrated circuit breaker pattern."""

from enum import Enum
from typing import Any
import time


class CircuitState(Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"


class CircuitBreaker:
    """Monitors failures and transitions between closed/open/half-open states."""

    def __init__(self, failure_threshold: int = 5, recovery_timeout: float = 30.0) -> None:
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.state: CircuitState = CircuitState.CLOSED
        self.failure_count: int = 0
        self.last_failure_time: float = 0.0

    def record_failure(self) -> None:
        self.failure_count += 1
        self.last_failure_time = time.monotonic()
        if self.failure_count >= self.failure_threshold:
            self.state = CircuitState.OPEN

    def record_success(self) -> None:
        self.failure_count = 0
        self.state = CircuitState.CLOSED

    def allow_request(self) -> bool:
        if self.state == CircuitState.CLOSED:
            return True
        if self.state == CircuitState.OPEN:
            if time.monotonic() - self.last_failure_time >= self.recovery_timeout:
                self.state = CircuitState.HALF_OPEN
                return True
            return False
        return True  # HALF_OPEN: allow one probe request

    def __repr__(self) -> str:
        return f"CircuitBreaker(state={self.state.value}, failures={self.failure_count})"


class MinMaxStack:
    """Stack supporting push, pop, top, getMin, getMax all in O(1).

    Integrates a circuit breaker that opens after repeated failures,
    halting operations until a recovery timeout elapses.

    Args:
        failure_threshold: Number of consecutive failures before opening the circuit.
        recovery_timeout: Seconds to wait before transitioning from open to half-open.
    """

    def __init__(self, failure_threshold: int = 5, recovery_timeout: float = 30.0) -> None:
        self._stack: list[Any] = []
        self._min_stack: list[Any] = []
        self._max_stack: list[Any] = []
        self._breaker = CircuitBreaker(failure_threshold, recovery_timeout)

    def _check_circuit(self) -> None:
        if not self._breaker.allow_request():
            raise RuntimeError(f"Circuit is open — operations blocked until recovery ({self._breaker})")

    def push(self, value: Any) -> None:
        """Push a value onto the stack. O(1)."""
        self._check_circuit()
        try:
            self._stack.append(value)
            self._min_stack.append(value if not self._min_stack else min(value, self._min_stack[-1]))
            self._max_stack.append(value if not self._max_stack else max(value, self._max_stack[-1]))
            self._breaker.record_success()
        except Exception:
            self._breaker.record_failure()
            raise

    def pop(self) -> Any:
        """Remove and return the top value. O(1)."""
        self._check_circuit()
        if not self._stack:
            self._breaker.record_failure()
            raise IndexError("pop from empty stack")
        try:
            self._min_stack.pop()
            self._max_stack.pop()
            self._breaker.record_success()
            return self._stack.pop()
        except IndexError:
            self._breaker.record_failure()
            raise

    def top(self) -> Any:
        """Return the top value without removing it. O(1)."""
        self._check_circuit()
        if not self._stack:
            self._breaker.record_failure()
            raise IndexError("top from empty stack")
        self._breaker.record_success()
        return self._stack[-1]

    def get_min(self) -> Any:
        """Return the minimum value in the stack. O(1)."""
        self._check_circuit()
        if not self._min_stack:
            self._breaker.record_failure()
            raise IndexError("get_min from empty stack")
        self._breaker.record_success()
        return self._min_stack[-1]

    def get_max(self) -> Any:
        """Return the maximum value in the stack. O(1)."""
        self._check_circuit()
        if not self._max_stack:
            self._breaker.record_failure()
            raise IndexError("get_max from empty stack")
        self._breaker.record_success()
        return self._max_stack[-1]

    @property
    def circuit(self) -> CircuitBreaker:
        """Access the underlying circuit breaker for inspection."""
        return self._breaker

    def __len__(self) -> int:
        return len(self._stack)

    def __bool__(self) -> bool:
        return bool(self._stack)

    def __repr__(self) -> str:
        return f"MinMaxStack({self._stack}, breaker={self._breaker})"
